const items = $input.all();
const recordCount = items.length;

let totalChinese = 0;
let totalEnglish = 0;
let totalMath = 0;
let validGradesCount = 0;

const parsedRecords = items.map(item => {
  const row = item.json;
  const c = parseFloat(row.chinese) || 0;
  const e = parseFloat(row.english) || 0;
  const m = parseFloat(row.math) || 0;
  if (row.chinese !== undefined || row.english !== undefined || row.math !== undefined) {
    totalChinese += c;
    totalEnglish += e;
    totalMath += m;
    validGradesCount++;
  }
  return {
    ...row,
    total_score: (c + e + m),
    average_score: Math.round(((c + e + m) / 3) * 10) / 10
  };
});

const summary = {
  status: 'success',
  message: '🎉 CSV 檔案已成功解析並完成統計運算！',
  total_records: recordCount,
  statistics: validGradesCount > 0 ? {
    avg_chinese: Math.round((totalChinese / validGradesCount) * 10) / 10,
    avg_english: Math.round((totalEnglish / validGradesCount) * 10) / 10,
    avg_math: Math.round((totalMath / validGradesCount) * 10) / 10,
    class_average: Math.round(((totalChinese + totalEnglish + totalMath) / (validGradesCount * 3)) * 10) / 10
  } : null,
  sample_preview: parsedRecords.slice(0, 3),
  processed_at: new Date().toISOString()
};

return [{ json: summary }];
